//! 🧪️ Stream cancellation removes its original edit without authoring a history transition or message.
use super::*;
#[test]
fn original_stream_abort_restores_projection_without_history_or_transport_trace(){
 type Abort=store::original_replay_publication::abort::OriginalStreamAbort<State,Mutation>;
 let law:serde_json::Value=serde_json::from_str(include_str!("abort.json")).unwrap();
 for cut in law["cancelCuts"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).chain([None]){
  let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);
  assert_eq!(store.snapshot().unwrap().zoom,law["genesis"].as_f64().unwrap());
  let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN};
  let result=crate::original_replay_publication::prepare_report(&mut store,&mut caller,&mut decoder);
  close_report_fixture(result,&mut caller,&mut decoder);
  let transaction=law["transaction"].as_str().unwrap().to_owned();
  {let parts=store.parts();parts.log.edit_sequence=1;parts.log.envelope.vcs.edits.iter_mut().next().unwrap().sequence_number=1;let edit_id=parts.log.envelope.vcs.edits.get(0).unwrap().id.clone();parts.log.envelope.open_transaction=Some(store::os_store::store_schema::OpenToolTransaction{transaction:protocol::TransactionRef{id:transaction.clone(),tool:String::from("energy#edit")},edit_id});*parts.live.current=Arc::new(State{zoom:law["streamed"].as_f64().unwrap()});}
  while !store.parts_ref().log.envelope.edit_messages.admission_is_complete(){let d=store.parts_ref().log.envelope.edit_messages.admission_demands().unwrap();turn(&mut caller,&mut decoder,g,|cx|{let grant=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|store.parts().log.envelope.edit_messages.admit_next(grant).map(|p|((),p)))?;Ok(())});}
  {let parts=store.parts();let id=parts.log.envelope.vcs.edits.get(0).unwrap().id.clone();parts.log.envelope.edit_messages.try_push(protocol::EditMessages{edit_id:id,messages:vec![protocol::MutationMessage::fatal("fixture.stream", "Original stream diagnostic λ")]}).unwrap();}
  let mut owner=None;let d=Abort::capture_demands();for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,_=>denied.maximum_depth=d.depth-1};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!Abort::admit(&store,&transaction,cx,&mut owner)?);Ok(())});assert!(owner.is_none());}turn(&mut caller,&mut decoder,g,|cx|{assert!(Abort::admit(&store,&transaction,cx,&mut owner)?);Ok(())});
  let mut foreign_decoder=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign_decoder,g,|cx|{assert!(owner.as_mut().unwrap().advance(&mut store,&transaction,cx).is_err());Ok(())});assert!(foreign_decoder.terminal_is_empty());let mut ready=false;for index in 0..262144{if cut==Some(index){break}ready=turn(&mut caller,&mut decoder,g,|cx|owner.as_mut().unwrap().advance(&mut store,&transaction,cx));assert_eq!(store.snapshot().unwrap().zoom,law["streamed"].as_f64().unwrap());assert_eq!(store.parts_ref().log.envelope.vcs.edits.len(),1);if ready{break}assert!(index<262143,"original stream abort preparation stalled");}
  if cut.is_none(){assert!(ready);turn(&mut caller,&mut decoder,g,|cx|{assert!(owner.as_mut().unwrap().publish(&mut store,cx)?);Ok(())});assert_eq!(store.snapshot().unwrap().zoom,law["restored"].as_f64().unwrap());assert!(store.parts_ref().log.envelope.vcs.edits.is_empty());assert_eq!(store.parts_ref().log.edit_sequence,0);assert!(store.parts_ref().log.envelope.edit_messages.is_empty());assert!(store.parts_ref().log.applied_edit_ids.is_empty());assert!(store.parts_ref().log.redo_edit_ids.is_empty());assert!(store.parts_ref().log.envelope.open_transaction.is_none());assert!(store.parts_ref().log.envelope.transitions.is_empty());assert!(store.parts_ref().wire.original_outbox.len()==0);}else{caller.cancel().cancel_now();}
  for index in 0..262144{if owner.as_ref().unwrap().terminal_is_empty(){break}let d=owner.as_ref().unwrap().close_demands(&store,4096).unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in 0..5{let mut denied=exact;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{assert!(!owner.as_mut().unwrap().close_step(&mut store,cx)?);Ok(())}));assert_eq!(owner.as_ref().unwrap().close_demands(&store,4096).unwrap(),d);}turn(&mut caller,&mut decoder,exact,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(&mut store,cx)));assert!(index<262143,"original stream abort closure stalled at {cut:?}: {d:?}");}
  turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Abort::boxed_release_demands();close_original_retained_step(cx,d,|_|{owner=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));
  for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}
pub(crate) fn close_report_fixture(mut result:store::os_store::replay::EditReplayResult<State,Mutation>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){result.begin_retirement();for index in 0..262144{if result.terminal_is_empty(){break}turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let grant=cx.retained_grant();let step=cx.with_native_retirement(|control|result.close_original_step_controlled(grant,control))?;cx.consume_retained(step.progress())?;cx.consume_fuel(step.progress().copied_items as u64);Ok(())}));assert!(index<262143);}}
